@@ -1,6 +1,37 @@
 export type Query = Record<string, string | string[]>;
+
+function decode(part: string): string {
+  const spaced = part.replace(/\+/g, " ");
+  try {
+    return decodeURIComponent(spaced);
+  } catch {
+    return spaced;
+  }
+}

 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const result: Query = {};
+  const body = query.startsWith("?") ? query.slice(1) : query;
+
+  for (const pair of body.split("&")) {
+    if (pair === "") continue;
+    const eq = pair.indexOf("=");
+    const key = decode(eq === -1 ? pair : pair.slice(0, eq));
+    const value = eq === -1 ? "" : decode(pair.slice(eq + 1));
+
+    const existing = Object.hasOwn(result, key) ? result[key] : undefined;
+    if (Array.isArray(existing)) {
+      existing.push(value);
+      continue;
+    }
+    // defineProperty so a key like "__proto__" becomes an own property instead of hitting the setter
+    Object.defineProperty(result, key, {
+      value: existing === undefined ? value : [existing, value],
+      writable: true,
+      enumerable: true,
+      configurable: true,
+    });
+  }
+  return result;
 }
